import { Prism, languages, insertBefore } from '../prismCore'
import './clike'
import './markup-templating'
import './php'

languages.latte = {
	'comment': /^\{\*[\s\S]*/,
	'latte-tag': {
		// https://latte.nette.org/en/tags
		pattern: /(^\{(?:\/(?=[a-z]))?)(?:[=_]|[a-z]\w*\b(?!\())/i,
		lookbehind: true,
		alias: 'important'
	},
	'delimiter': {
		pattern: /^\{\/?|\}$/,
		alias: 'punctuation'
	},
	'php': {
		pattern: /\S(?:[\s\S]*\S)?/,
		alias: 'language-php',
		inside: 'php'
	}
};

var markupLatte = languages.extend('markup', {});
insertBefore('inside', 'attr-value', {
	'n-attr': {
		pattern: /n:[\w-]+(?:\s*=\s*(?:"[^"]*"|'[^']*'|[^\s'">=]+))?/,
		inside: {
			'attr-name': {
				pattern: /^[^\s=]+/,
				alias: 'important'
			},
			'attr-value': {
				pattern: /=[\s\S]+/,
				inside: {
					'punctuation': [
						/^=/,
						{
							pattern: /^(\s*)["']|["']$/,
							lookbehind: true
						}
					],
					'php': {
						pattern: /\S(?:[\s\S]*\S)?/,
						inside: 'php'
					}
				}
			},
		}
	},
}, markupLatte.tag);

Prism.hooks.add('before-tokenize', env => {
	if (env.language == 'latte') {
		var lattePattern = /\{\*[\s\S]*?\*\}|\{[^'"\s{}*](?:[^"'/{}]|\/(?![*/])|("|')(?:\\[\s\S]|(?!\1)[^\\])*\1|\/\*(?:[^*]|\*(?!\/))*\*\/)*\}/g;
		languages['markup-templating'].buildPlaceholders(env, 'latte', lattePattern);
		env.grammar = markupLatte;
	}
});

Prism.hooks.add('after-tokenize', env => {
	languages['markup-templating'].tokenizePlaceholders(env, 'latte');
});
